agent-task.code:
// SnakeStick이 SlopDisk에 요구하는 계약. 이름과 시그니처 세부는 SlopDisk 설계에 맞춰 바꿔도 된다.
struct SDPatch { let offset: UInt64; let bytes: Data }

imagine func retargeted(_ image: SDDiskImage, diskSize: UInt64, blockSize: Int) throws -> [SDPatch] {
    requirements(`
        image의 GPT를 diskSize 크기 디스크에 맞게 다시 계산해 바이트 패치로 돌려준다.
        패치는 둘이다. 앞쪽은 LBA 0~1 (protective MBR + primary GPT 헤더), 뒤쪽은 디스크 끝의 백업 엔트리 배열 + 백업 헤더.
        protective MBR의 0xEE 엔트리 크기, primary 헤더의 AlternateLBA·LastUsableLBA와 헤더 CRC가 바뀐다.
        파티션 엔트리 내용은 바뀌지 않는다.
        어떤 파일이나 디바이스에도 쓰지 않는다 (결정 3).
    `);
    ensure(patches.count == 2);
    ensure(patches[0].offset == 0 && patches[0].bytes.count == 2 * blockSize);
    ensure(patches[1].offset + UInt64(patches[1].bytes.count) == diskSize);
    ensure(SDDiskImage.open(.file(applyToSparseFile(image, patches, size: diskSize))).gptHealth == .primaryAndBackupValid);
    ensure(throws: retargeted(image, diskSize: image.partitions.last!.end, blockSize: blockSize), "백업 GPT가 들어갈 자리가 없으면 거부한다");
}
